/** CSS and CSV export. Pure functions, unit tested. */

import { cssClass, cssContent, ruleFor, viewBoxFor } from './glyph.js';
import { csvCell, escapeXml, slugify, unicodeLabel } from './text.js';

const plural = (count, singular, pluralForm) => (count === 1 ? singular : pluralForm);

export const generateCss = (glyphs, family, prefix) => {
  const header =
    '/* ' +
    family +
    ' — ' +
    glyphs.length +
    ' ' +
    plural(glyphs.length, 'glyph', 'glyphs') +
    '\n' +
    ' * Generated by Glyphary · prefix .' +
    prefix +
    '\n' +
    ' * Include the original @font-face in your project.\n' +
    ' */\n\n';
  return header + glyphs.map((glyph) => ruleFor(glyph, prefix)).join('\n') + '\n';
};

export const generateCsv = (glyphs, prefix) => {
  const rows = [['glyph_name', 'unicode', 'codepoint_decimal', 'css_content', 'css_class']];
  glyphs.forEach((glyph) => {
    rows.push([glyph.name, unicodeLabel(glyph), glyph.cps.join(' '), cssContent(glyph), cssClass(glyph, prefix)]);
  });
  // BOM so Excel opens the file as UTF-8.
  return '\ufeff' + rows.map((row) => row.map(csvCell).join(',')).join('\r\n') + '\r\n';
};

export const fileBase = (family) => slugify(family) || 'font';

/** Standalone SVG file for a single glyph (screen preview, not the outline font). */
export const generateGlyphSvg = (glyph, metrics) =>
  '<?xml version="1.0" encoding="UTF-8"?>\n' +
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="' +
  viewBoxFor(glyph, metrics) +
  '">\n' +
  '  <g transform="scale(1,-1)">\n' +
  '    <path fill="#1b1a17" d="' +
  escapeXml(glyph.d) +
  '"/>\n' +
  '  </g>\n' +
  '</svg>\n';
